fn publish(){assert!(!Path::new(D).exists());let a=read(r("analysis.json"));assert_eq!(a["new_independent_exports"],438);assert_eq!(a["independent_proof_count"],21697);assert_eq!(a["SDK_requests"],20802);assert_eq!(a["calibration_gate_required"],false);assert_eq!(read(r("runs/result.json"))["status"],"complete");let pins=read(r("pins.json"));for(p,h)in pins.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}let manifest=read("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-29-balanced-kh-adoption/artifacts/production-source-manifest.json");for(f,h)in manifest["source_files_sha256"].as_object().unwrap(){assert_eq!(hash(Path::new("/home/ubuntu/src/zk-tools/zopro").join(f)),h.as_str().unwrap());}assert_eq!(read(r("proof-sha256-after.json")).as_array().unwrap().len(),21697);
let dest=Path::new(D);let art=dest.join("artifacts");fs::create_dir_all(&art).unwrap();let names=["analysis.json","design.md","setup.rs","native.rs","prepare.rs","component-original.rs","representative.rs","capture.rs","prepare-capture.rs","publish.rs","publication.rs","prepare-publication.rs","build-plan.json","build-pins.json","run-plan.json","pins.json","source-audit.json","identities.json","cases.json","jobs.json","proof-inventory.json","proof-sha256-after.json","prior-proof-sha256.json","native-flags-control.txt","native-flags-candidate.txt","frozen-control.json","frozen-candidate.json"];
for f in names{fs::copy(r(f),art.join(f)).unwrap();}let mut source=files(&r("source"));assert_eq!(source.len(),176);source.extend(names.into_iter().map(r));let source_archive=archive(&source,Path::new(R),&art.join("source.json.gz"));let mut receipts=vec![];for sub in["native","runs","initial-capture-setup"]{for p in files(&r(sub)){let mut f=fs::File::open(&p).unwrap();let mut magic=[0;4];let n=f.read(&mut magic).unwrap();if n==4&&magic==[127,b'E',b'L',b'F']{continue}receipts.push(p);}}let receipt_archive=archive(&receipts,Path::new(R),&art.join("receipts.json.gz"));let proof_files=files(&r("proofs"));assert_eq!(proof_files.len(),876);let proof_archive=archive(&proof_files,Path::new(R),&art.join("proofs.json.gz"));let mut local=BTreeMap::new();for p in files(&r("perf")).into_iter().chain(files(&r("codegen"))).chain([r("native/control-sdk"),r("native/candidate-sdk")]){local.insert(p.display().to_string(),hash(p));}save(art.join("local-artifacts.json"),&json!(local));save(art.join("publication-review.json"),&json!({"source":source_archive,"receipts":receipt_archive,"proofs":proof_archive,"all_capture_pins_closed":true,"production175_unchanged":true,"parent_constructor_gate":false,"new_full_request_protocol":true,"new_independent_exports":438,"ledger":21697,"adopted":false,"goal_achieved":false}));
let pass=a["gate_passed"].as_bool().unwrap();let mut md=format!("# One pass representative grouping in complete SDK proofs\n\nThe new complete-request performance gate **{}**. Production remains unchanged. This independently measures the [representative constructor](../2026-10-29-representative-groups175/README.md) in complete SDK requests across all nine circuits. Its earlier constructor gate remains failed: primary gains of 21.5%/23.3% and an improving aggregate coexist with eight larger constructor regressions. None of those observations is relabeled or excluded.\n\n## Implementation and scope\n\nA private native cfg selects one hash pass with compact original-row/count records and existing row classes. Full scalar values and usize counts are materialized only after exact admission; records are released before stable output packing. The compact dictionary checks all four words through borrowed immutable input. First-occurrence order, zeros, cutoffs, sample policy and query independence remain. No point copy, key table, duplicate plan, new pool, unsafe code or field operation is added.\n\nThe clean private snapshot has 176 files: 172 of 175 originals are exact; grouping.rs, core Cargo.toml and Cargo.lock have reversible changes, plus one child. The native-only hashbrown 0.16.1 dependency has default features disabled and inline-more enabled. All 17 field files remain exact and their 33-test qualification is inherited. The original grouping allocation forecast covers the new record lifetimes; this is not a minimum-RAM or pressure qualification.\n\nThe decision to run this new protocol evaluates whole-request latency and memory despite a phase-level 3% failure. It does not waive the old constructor gate or adopt a favorable subset. All nine latency rows are retained.\n\n## Complete request measurements\n\nRyzen 9 9950X, 16 physical cores and 32 logical CPUs, with 32 workers pinned to CPUs 0–31. Fifteen fixed rotated/reversed case and variant blocks compare the exact accepted executable, fresh OFF and ON. Each primary process times 151 requests after three primes; other circuits time 31 after three primes. Loading/preparation are outside latency and inside lifetime RSS. Fresh solving, randomized proving, SDK verification and serialization are timed. Ratios pair process medians within blocks and need not equal ratios of displayed medians.\n\n|Circuit|Accepted ms|OFF ms|ON ms|ON/accepted ratio|Bounds|Wins / 15|ON/OFF ratio|Bounds|Wins / 15|\n|---|---:|---:|---:|---:|---|---:|---:|---|---:|\n",if pass{"passes"}else{"fails"});let cases=read(r("cases.json"));for c in cases.as_array().unwrap().iter().filter(|c|c["workers"]==32){let n=c["name"].as_str().unwrap();let m=|v:&str|a["cells"][format!("{n}/{v}")]["median_ms"].as_f64().unwrap();let p=&a["pairs"][format!("{n}/ON/accepted")];let q=&a["pairs"][format!("{n}/ON/OFF")];md+=&format!("|{}|{:.6}|{:.6}|{:.6}|{:.9}|[{:.9}, {:.9}]|{}|{:.9}|[{:.9}, {:.9}]|{}|\n",c["shape"].as_str().unwrap(),m("accepted"),m("OFF"),m("ON"),p["median"].as_f64().unwrap(),p["low"].as_f64().unwrap(),p["high"].as_f64().unwrap(),p["wins"],q["median"].as_f64().unwrap(),q["low"].as_f64().unwrap(),q["high"].as_f64().unwrap(),q["wins"]);}
md+="\n|Original eight aggregate versus|Ratio|Bounds|Wins / 15|\n|---|---:|---|---:|\n";for(k,v)in a["original8_aggregates"].as_object().unwrap(){md+=&format!("|{k}|{:.9}|[{:.9}, {:.9}]|{}|\n",v["median"].as_f64().unwrap(),v["low"].as_f64().unwrap(),v["high"].as_f64().unwrap(),v["wins"]);}
md+="\n## CPU time and memory\n\nRSS is the maximum process lifetime high-water mark across blocks, including loading and primes, in MiB. It is not incremental workspace or minimum RAM. CPU time sums user and system time per request.\n\n|Circuit|Accepted CPU ms|OFF CPU ms|ON CPU ms|Accepted peak RSS MiB|OFF peak RSS MiB|ON peak RSS MiB|\n|---|---:|---:|---:|---:|---:|---:|\n";for c in cases.as_array().unwrap().iter().filter(|c|c["workers"]==32){let n=c["name"].as_str().unwrap();let x=|v:&str,k:&str|a["cells"][format!("{n}/{v}")][k].as_f64().unwrap();md+=&format!("|{}|{:.3}|{:.3}|{:.3}|{:.2}|{:.2}|{:.2}|\n",c["shape"].as_str().unwrap(),x("accepted","CPU_ms"),x("OFF","CPU_ms"),x("ON","CPU_ms"),x("accepted","max_RSS_MiB"),x("OFF","max_RSS_MiB"),x("ON","max_RSS_MiB"));}
md+="\n## Declared checks and calibration\n\nPrimary ON/accepted and ON/OFF require upper paired ratio <1 and at least 10 wins. Both original-eight equal-log aggregates require upper <1 and at least 10 wins. Every circuit's ON/control upper ratio must be ≤1.02 against both controls, and observed ON peak RSS must be ≤1.05× each control. The memory allowance is relative, not a fixed architecture RAM cap. Ranks 4–12 of 15 give nominal 96.484375% individual median coverage under independent/exchangeable blocks, not a familywise guarantee. No gain floor, exclusion, extension, layout/seed selection, threshold change or unchanged rerun is applied.\n\nOFF/accepted intervals within factor 1.03 are reported as calibration diagnostics in this new protocol, not a performance gate. Both exact-artifact comparisons remain required. A control difference limits source-level causal attribution; it does not erase the directly paired candidate/accepted observation. Earlier failed calibration gates and the accepted build's documented physical-16 engineering exception remain unchanged.\n\nFailed performance checks:\n\n";for f in a["failed_checks"].as_array().unwrap(){md+=&format!("- `{}`\n",f.as_str().unwrap());}if a["failed_checks"].as_array().unwrap().is_empty(){md+="None.\n";}md+="\nCalibration diagnostics outside factor 1.03:\n\n";let mut bad=0;for(k,v)in a["calibration_checks"].as_object().unwrap(){if v==false{bad+=1;let p=&a["pairs"][k];md+=&format!("- `{k}`: [{:.9}, {:.9}].\n",p["low"].as_f64().unwrap(),p["high"].as_f64().unwrap());}}if bad==0{md+="None.\n";}
md+="\n## Correctness and automatic profiling\n\nFresh OFF/ON pass 124/127 unfiltered native core tests and eight/eight prover tests. Three native child tests adapt the parent constructor's collision, whole-output, cutoff, immutable-input and allocation-bound checks. The parent algorithm is unchanged apart from result/reservation ownership and the private dispatch. No new field suite is counted.\n\nAll 27 preflight exports pass independent Gnark verification before latency. All 405 latency processes precede six separate FIFO-gated 199 Hz cycles:u recordings: primary at 16 and 32 workers, accepted/OFF/ON, 251 requests after three primes. CPU IDs and timestamps are explicit. Physical-16 profiles are diagnostic, not a new latency qualification. All recordings precede ownership transfer, the remaining 411 independent verifications, owner-user decoding and lost-record audits. No owned compiler/helper/hash/archive or second CPU workload overlaps capture.\n\n|Profile|Samples|Lost records|\n|---|---:|---:|\n";for(k,v)in a["diagnostics"]["profiles"].as_object().unwrap(){md+=&format!("|{k}|{}|0|\n",v["samples"]);}
md+="\nAll profiles have one sampled SDK process and zero lost records. Flat symbols and static assembly do not establish exclusive cache, allocator, spill or critical-path costs. All 900 workflow steps complete. A capture-helper preparation initially stopped before producing capture.rs because an exact-match transformation expected a different inherited string spelling. Correcting only that transformation preserves runtime source and the declared protocol; no successful build/test/capture is repeated. The initial source and failure are archived.\n\nThe trial totals **20,802 internally verified SDK requests and 438 fresh independent Gnark exports**, with 876 proof/public members. Every retained proof is 164 bytes, fixture/public-bound and distinct from all 21,259 prior proof identities. The ledger is **21,697** after verification. Source, receipt and proof archives round-trip byte-exactly.\n\n## Supplied M5 comparisons and decision\n\nM5 CPU/Metal values are supplied historical references, not newly measured Apple results. ON times below are experimental full-proof measurements, not adopted production performance.\n\n|Circuit|ON ms|M5 CPU ms|CPU speedup|M5 Metal ms|Metal speedup|CPU 10× target ms|\n|---|---:|---:|---:|---:|---:|---:|\n";let mut reached=0;for c in cases.as_array().unwrap().iter().filter(|c|c["workers"]==32){let n=c["name"].as_str().unwrap();let ms=a["cells"][format!("{n}/ON")]["median_ms"].as_f64().unwrap();if c["reference"].is_null(){md+=&format!("|{}|{ms:.6}|—|—|—|—|—|\n",c["shape"].as_str().unwrap());}else{let cpu=c["reference"]["cpu_ms"].as_f64().unwrap();let metal=c["reference"]["metal_ms"].as_f64().unwrap();if ms<=cpu/10.{reached+=1}md+=&format!("|{}|{ms:.6}|{cpu:.0}|{:.3}×|{metal:.0}|{:.3}×|{:.1}|\n",c["shape"].as_str().unwrap(),cpu/ms,metal/ms,cpu/10.);}}
md+=&format!("\nThe candidate reaches {reached}/8 supplied CPU 10× latency targets in these measurements. The original objective remains active and unproven. There is no supplied M5 reference for 54→1.\n\n");md+=if pass{"This performance result selects separate portable/resource/admission/concurrency and final-artifact qualification before any adoption.\n\n"}else{"The declared complete-request gate fails, so this implementation is not adopted. Every positive estimate, memory observation and failed check remains in the record; no favorable subset is promoted.\n\n"};md+="Accepted production remains 175 files, with qualified local 1×2 8.022165 ms and 134 MiB peak RSS. The latest AWS 1×2 remains Zopro 11.915591 ms at 32 workers versus Aeglos 7.959184 ms at 96. No new AWS, phone/ARM/TEE, forester 250/4999, pressure/swap, minimum-RAM or concurrent-throughput result is claimed. [Current local/AWS summary](../2026-10-29-current-cpu-summary/README.md).\n\n[Protocol](artifacts/design.md), [all observations and checks](artifacts/analysis.json), [implementation](artifacts/representative.rs), [source audit](artifacts/source-audit.json), [source](artifacts/source.json.gz), [receipts](artifacts/receipts.json.gz), [proofs](artifacts/proofs.json.gz), [publication review](artifacts/publication-review.json).\n";fs::write(dest.join("README.md"),md).unwrap();let sums=files(dest).into_iter().map(|p|format!("{}  {}\n",hash(&p),p.strip_prefix(dest).unwrap().display())).collect::<String>();fs::write(dest.join("SHA256SUMS"),sums).unwrap();println!("PublishedfullSDKgate{pass};176privatesources,{}receiptmembers,876proof/publicmembers;ledger21697",receipts.len());}
